package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class MaintenanceCenter {
 static JSONObject dashboard(MainActivity c)throws Exception{JSONObject out=OperationOverview.read(c);JSONArray cards=out.getJSONArray("cards");JSONArray jobs=CancellableWork.list(c);for(int i=0;i<jobs.length();i++){JSONObject row=jobs.getJSONObject(i);String phase=MaintenancePolicy.phase(row.optString("phase"));cards.put(new JSONObject().put("label",phase).put("title",row.optString("kind")).put("id",row.optString("id")).put("detail","送信試行 "+row.optInt("sentRequests")+"回 / "+row.optLong("sentBytes")+"バイト。"+MaintenancePolicy.next(phase)));}out.put("schedule",ScheduledTransfer.read(c));return out;}
 static JSONObject preflight(Context c)throws Exception{android.content.pm.PackageInfo p=c.getPackageManager().getPackageInfo(c.getPackageName(),android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES);android.content.pm.Signature[] sig=p.signingInfo==null?new android.content.pm.Signature[0]:p.signingInfo.getApkContentsSigners();JSONArray certs=new JSONArray();for(android.content.pm.Signature v:sig)certs.put(RecorderPhotoStore.hash(v.toByteArray()));JSONObject state=ConversationWorkspace.snapshot(c);return new JSONObject().put("phoneVersion",p.getLongVersionCode()).put("signingSha256",certs).put("freeBytes",c.getFilesDir().getUsableSpace()).put("phone",ScheduledTransfer.environment(c)).put("glassFresh",state.optBoolean("connected")).put("glass",state.optJSONObject("departure")==null?new JSONObject():state.getJSONObject("departure")).put("message","更新候補APKとの署名・版番号比較は付属の更新前チェックを実行してください。この画面は更新しません。古いAPKへの戻しでは新しい保存形式の互換性を保証できないため、アンインストールせず復旧手順を確認してください");}
 static JSONObject diagnosis(Context c)throws Exception{JSONObject state=ConversationWorkspace.snapshot(c),env=ScheduledTransfer.environment(c);JSONArray steps=new JSONArray();steps.put(new JSONObject().put("title","スマホの回線").put("state",env.optBoolean("wifi")?"Wi-Fi接続あり":"Wi-Fi未確認・モバイル回線は別確認").put("action","Androidのネットワーク設定を開き、利用する回線を確認"));steps.put(new JSONObject().put("title","グラスとの接続").put("state",state.optBoolean("connected")?"15秒以内の状態を受信":"新しい状態を受信していません").put("action",state.optBoolean("connected")?"操作結果は処理状況で確認":"両端末の電源・Bluetooth・接続先を確認し、グラスのロキを開いて再確認"));steps.put(new JSONObject().put("title","Web接続").put("state","個別接続の失効・権限はスマホ本体で確認").put("action","スマホと閲覧端末の回線を確認し、共有画面から接続先を開き直す。認証切れならスマホで再共有"));steps.put(new JSONObject().put("title","転送・解析").put("state","通信成功と保存完了は別に確認").put("action","処理状況→保存照合の順に確認。未確認の依頼は重複送信しない"));return new JSONObject().put("steps",steps).put("at",System.currentTimeMillis());}
 static long[] walk(File root,File file,int[] budget)throws Exception{if(--budget[0]<0)throw new IOException("ファイル数が多いため未集計です");if(!file.getCanonicalFile().toPath().startsWith(root.getCanonicalFile().toPath()))throw new IOException("保存先の外部参照を検出しました");if(java.nio.file.Files.isSymbolicLink(file.toPath()))throw new IOException("外部参照は集計しません");if(!file.exists())return new long[]{0,0};if(file.isFile())return new long[]{file.length(),1};long bytes=0,count=0;File[] children=file.listFiles();if(children==null)throw new IOException("一覧を読み取れません");for(File f:children){long[] x=walk(root,f,budget);bytes+=x[0];count+=x[1];}return new long[]{bytes,count};}
 static JSONObject capacity(Context c)throws Exception{File base=c.getFilesDir();JSONArray items=new JSONArray(),issues=new JSONArray();String[][] groups={{"写真","recorder-photos"},{"会議音声・要約","meeting-audio"},{"生成画像","generated-images"},{"生成動画","generated-videos"}};for(String[] group:groups){JSONObject row=new JSONObject().put("title",group[0]);try{long[] n=walk(base,new File(base,group[1]),new int[]{10000});row.put("bytes",n[0]).put("files",n[1]);}catch(Exception e){row.put("unavailable",true);issues.put(group[0]);}items.put(row);}return new JSONObject().put("items",items).put("issues",issues).put("freeBytes",base.getUsableSpace()).put("noteTrash",PersonalNotes.trash(c).length()).put("inboxTrash",SecretaryInbox.trash(c).length()).put("retentionDays",c.getSharedPreferences("maintenance_capacity",0).getInt("days",30)).put("message","ファイル容量は暗号化済み実ファイルの集計です。保持日数は整理の目安で、自動削除はしません。写真・音声・生成物は各一覧で確認して個別削除してください。ごみ箱は履歴画面から個別に完全削除できます");}
 static JSONObject get(MainActivity c,String route,Map<String,String> q)throws Exception{switch(route){case "maintenance-record-target":return RecordAnchors.target(c,q.getOrDefault("id",""),Long.parseLong(q.getOrDefault("anchor","0")));case "maintenance-attention":return AttentionHub.read(c);case "maintenance-duplicates":return new JSONObject().put("items",DuplicateReview.pairs(c)).put("scope","有効メモ100件の文字類似度と、直近200写真の受領ハッシュから候補を表示。写真は削除直前に両方の実データを復号照合。自動整理しません");case "maintenance-usage":return UsageLedger.read(c);case "maintenance-settings-search":return new JSONObject().put("items",ExperiencePolicy.settings(q.getOrDefault("q","")));case "maintenance-lease":return MaintenanceLease.status(c);case "maintenance-meetings":return new JSONObject().put("items",MeetingAudioStore.list(c));case "maintenance-search":return MaintenanceSearch.search(c,q.getOrDefault("q",""),new JSONObject().put("type",q.getOrDefault("type","")).put("from",Long.parseLong(q.getOrDefault("from","0"))).put("until",Long.parseLong(q.getOrDefault("until",String.valueOf(Long.MAX_VALUE)))).put("pending",q.getOrDefault("pending","false").equals("true")));case "maintenance-status":return dashboard(c);case "maintenance-preflight":return preflight(c);case "maintenance-capacity":return capacity(c);case "maintenance-diagnosis":return diagnosis(c);case "maintenance-tasks":return new JSONObject().put("items",MeetingTaskBoard.list(c));case "maintenance-candidates":return MeetingTaskBoard.source(c,q.getOrDefault("id",""));case "maintenance-schedule":return ScheduledTransfer.read(c);case "maintenance-display":return DisplayPreferences.read(c);default:throw new IOException("画面を確認してください");}}
 static JSONObject post(MainActivity c,String route,JSONObject v)throws Exception{switch(route){case "maintenance-schedule-notifications":TransferResultNotice.set(c,v.getBoolean("enabled"));return new JSONObject().put("message","結果通知の設定を保存しました。Android側で通知が許可済みの場合に、音なしで表示します");case "maintenance-task-edit":return MeetingTaskBoard.edit(c,v);case "maintenance-duplicate-cleanup":return DuplicateReview.cleanup(c,v);case "maintenance-usage-rates":UsageLedger.rates(c,v);return new JSONObject().put("message","利用者指定の単価を保存しました。請求額ではありません");case "maintenance-task-save":return MeetingTaskBoard.save(c,v);case "maintenance-task-change":return MeetingTaskBoard.change(c,v.getString("id"),v.getInt("revision"),v.getString("state"));case "maintenance-schedule-save":return ScheduledTransfer.schedule(c,v);case "maintenance-schedule-cancel":return ScheduledTransfer.cancel(c,v.getString("id"));case "maintenance-schedule-run":return ScheduledTransfer.dispatch(c,v.getString("id"),true);case "maintenance-display-save":DisplayPreferences.save(c,v);return new JSONObject().put("message","表示設定を保存しました。画面を開き直してください");case "maintenance-retention":int days=v.getInt("days");if(days!=7&&days!=30&&days!=90)throw new IOException("保持期間の目安を選んでください");if(!c.getSharedPreferences("maintenance_capacity",0).edit().putInt("days",days).commit())throw new IOException("保存できません");return new JSONObject().put("message","整理の目安を保存しました。自動削除しません");default:throw new IOException("操作を確認してください");}}
 private MaintenanceCenter(){}
}
